import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Multiplication-Operator.md","filePath":"manual-zh/Matrix-Multiplication-Operator.md","lastUpdated":1785684581000}'),r={name:"manual-zh/Matrix-Multiplication-Operator.md"};function c(i,t,p,n,l,_){return a(),o("div",null,[...t[0]||(t[0]=[d('<h4 id="_16-4-1-6-矩阵乘法运算符" tabindex="-1">16.4.1.6 矩阵乘法运算符 ‘*’ <a class="header-anchor" href="#_16-4-1-6-矩阵乘法运算符" aria-label="Permalink to &quot;16.4.1.6 矩阵乘法运算符 ‘*’&quot;">​</a></h4><p>如果 <code>A</code> 是 <em>m ×n</em> 矩阵，<code>B</code> 是 <em>n ×p</em> 矩阵，则 <code>A*B</code> 是 <em>m ×p</em> 矩阵乘法乘积 <code>C</code>。如果 <code>A</code> 的列数与 <code>B</code> 的行数不同，PSPP 会报错。</p><p>如果其中一个操作数为标量，则 <code>*</code> 运算符执行逐元素乘法（见上文）。</p><p>没有内置运算符求矩阵乘法的逆。应改为乘以 <code>INV</code> 或 <code>GINV</code> 的结果。</p><p>一些示例：</p><table tabindex="0"><thead><tr><th>{1, 2, 3} * {4; 5; 6}</th><th>⇒</th><th>32</th></tr></thead><tbody><tr><td>{4; 5; 6} * {1, 2, 3}</td><td>⇒</td><td>{4, 8, 12; 5, 10, 15; 6, 12, 18}</td></tr></tbody></table>',6)])])}const h=e(r,[["render",c]]);export{s as __pageData,h as default};
